# Write the DejaVu fonts OpenVSP draws text with as C++ byte arrays, so no font file is read at run time.
#
#   python make_font_source.py <dejavu-fonts-ttf-2.37/ttf>
#
# rewrites DejaVuSans.cpp, DejaVuSansOblique.cpp, DejaVuSansBold.cpp and DejaVuSansBoldOblique.cpp beside this
# script.  The output is committed; building
# OpenVSP needs neither Python nor the fonts.

import os
import sys

FONTS = [ ( "DejaVuSans.ttf", "DejaVuSans.cpp", "dejavu_sans_ttf" ),
          ( "DejaVuSans-Oblique.ttf", "DejaVuSansOblique.cpp", "dejavu_sans_oblique_ttf" ),
          ( "DejaVuSans-Bold.ttf", "DejaVuSansBold.cpp", "dejavu_sans_bold_ttf" ),
          ( "DejaVuSans-BoldOblique.ttf", "DejaVuSansBoldOblique.cpp", "dejavu_sans_bold_oblique_ttf" ) ]

HEADER = """//
// DejaVu fonts are (c) Bitstream, with DejaVu changes in the public domain; see LICENSE beside this file.
//
// Generated by make_font_source.py from %s of DejaVu 2.37.  Do not edit.
//

#include "DejaVuFonts.h"

const unsigned int %s_size = %d;

const unsigned char %s[] = {
"""


def write_font( ttf, cpp, name ):
    data = open( ttf, "rb" ).read()
    lines = []
    for i in range( 0, len( data ), 24 ):
        lines.append( "    " + ",".join( str( b ) for b in data[i:i + 24] ) + "," )
    with open( cpp, "w", newline="\n" ) as f:
        f.write( HEADER % ( os.path.basename( ttf ), name, len( data ), name ) )
        f.write( "\n".join( lines ) )
        f.write( "\n};\n" )
    print( "%s: %d bytes" % ( cpp, len( data ) ) )


if __name__ == "__main__":
    if len( sys.argv ) != 2:
        sys.exit( "usage: python make_font_source.py <dejavu-fonts-ttf-2.37/ttf>" )
    here = os.path.dirname( os.path.abspath( __file__ ) )
    for ttf, cpp, name in FONTS:
        write_font( os.path.join( sys.argv[1], ttf ), os.path.join( here, cpp ), name )
